@layer components {
  /* Component-tier token aliases */
  :root {
    --shelf-profile-card-bgColor-base: var(--shelf-bgColor-surface);
    --shelf-profile-card-borderColor-base: var(--shelf-borderColor-subtle);
    --shelf-profile-card-fgColor-title: var(--shelf-fgColor-default);
    --shelf-profile-card-fgColor-subtitle: var(--shelf-fgColor-muted);
    --shelf-profile-card-bgColor-skeleton: var(--shelf-bgColor-skeleton);
    --shelf-profile-card-bgColor-shimmer: var(--shelf-bgColor-shimmer);
  }

  [data-theme="dark"] {
    --shelf-profile-card-bgColor-base: var(--shelf-bgColor-surface);
    --shelf-profile-card-borderColor-base: var(--shelf-borderColor-subtle);
    --shelf-profile-card-fgColor-title: var(--shelf-fgColor-default);
    --shelf-profile-card-fgColor-subtitle: var(--shelf-fgColor-muted);
    --shelf-profile-card-bgColor-skeleton: var(--shelf-bgColor-skeleton);
    --shelf-profile-card-bgColor-shimmer: var(--shelf-bgColor-shimmer);
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --shelf-profile-card-bgColor-base: var(--shelf-bgColor-surface);
      --shelf-profile-card-borderColor-base: var(--shelf-borderColor-subtle);
      --shelf-profile-card-fgColor-title: var(--shelf-fgColor-default);
      --shelf-profile-card-fgColor-subtitle: var(--shelf-fgColor-muted);
      --shelf-profile-card-bgColor-skeleton: var(--shelf-bgColor-skeleton);
      --shelf-profile-card-bgColor-shimmer: var(--shelf-bgColor-shimmer);
    }
  }

  .profile-card {
    background-color: var(--shelf-profile-card-bgColor-base);
    border: var(--shelf-borderWidth-thin) solid var(--shelf-profile-card-borderColor-base);
    border-radius: var(--shelf-borderRadius-md);
    padding: var(--shelf-spacing-md);
    display: flex;
    flex-direction: column;
    gap: var(--shelf-spacing-xs);
  }

  .profile-card-title {
    color: var(--shelf-profile-card-fgColor-title);
    font-size: var(--shelf-fontSize-md);
    font-weight: var(--shelf-fontWeight-semibold);
  }

  .profile-card-subtitle {
    color: var(--shelf-profile-card-fgColor-subtitle);
    font-size: var(--shelf-fontSize-sm);
  }

  /* Skeleton variant */
  .profile-card--skeleton .skeleton-bar {
    background-color: var(--shelf-profile-card-bgColor-skeleton);
    border-radius: var(--shelf-borderRadius-sm);
    height: var(--shelf-size-skeletonBar);
    overflow: hidden;
    position: relative;
  }

  .profile-card--skeleton .skeleton-bar--full {
    width: 100%;
  }

  .profile-card--skeleton .skeleton-bar--short {
    width: 60%;
  }

  .profile-card--skeleton .skeleton-bar::after {
    content: "";
    position: absolute;
    inset: 0;
    background-color: var(--shelf-profile-card-bgColor-shimmer);
    transform: translateX(-100%);
    animation: profile-card-shimmer var(--shelf-duration-slow) var(--shelf-easing-linear) infinite;
  }

  @keyframes profile-card-shimmer {
    to {
      transform: translateX(100%);
    }
  }
}
